![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

To ensure the validator fails closed when input files are missing or malformed, we should validate the parsed file shape, record malformed entry diagnostics, and pass those diagnostics into the package validator to fail closed. This aligns with the repository's general rules on fail-closed validation.

```javascript
function buildValidator({ rows, refs, readback, generatedAt, diagnostics = [] }) {
  const approvedRows = rows.filter((row) => row.source_visual_receipt_approved === true || row.student_display_eligible_final === true);
  const acceptedRefs = asArray(refs.accepted_source_visual_receipt_refs);
  const missingEvidenceNotBlocked = rows.filter((row) => (
    row.evidence.source_page_render_ref === null
    || row.evidence.bbox === null
    || row.evidence.rights_display_status !== 'rights_display_allowed'
    || !row.evidence.question_render_model_ref
  ) && row.review_status !== 'blocked');
  const completeEvidenceAccepted = rows.filter((row) => row.blockers.length === 0 && row.review_status !== 'needs_human_review');
  const hasErrors = diagnostics.some((d) => d.severity === 'error');
  const checks = [
    check('no_input_diagnostics', !hasErrors, {
      diagnostics,
    }),
    check('no_final_display_acceptance', approvedRows.length === 0 && acceptedRefs.length === 0 && readback.student_display_eligible_final_count === 0, {
      approved_row_count: approvedRows.length,
      accepted_ref_count: acceptedRefs.length,
      student_display_eligible_final_count: readback.student_display_eligible_final_count,
    }),
    check('missing_evidence_fails_closed', missingEvidenceNotBlocked.length === 0, {
      sample_question_keys: missingEvidenceNotBlocked.slice(0, 10).map((row) => row.question_key),
    }),
    check('complete_evidence_needs_owner_review_only', completeEvidenceAccepted.length === 0, {
      sample_question_keys: completeEvidenceAccepted.slice(0, 10).map((row) => row.question_key),
    }),
    check('refs_are_runtime_gate_compatible', refs.schema_version === 'source_visual_receipt_replay_refs.v1' && asArray(refs.rows).length === rows.length, {
      refs_row_count: asArray(refs.rows).length,
      replay_candidate_count: rows.length,
    }),
  ];
  const failedChecks = checks.filter((item) => item.status !== 'pass');
  return {
    schema_version: 'source_visual_receipt_replay_validator.v1',
    generated_at: generatedAt,
    ok: failedChecks.length === 0,
    summary: {
