function validateInputs(inputs, paths) {
  const diagnostics = [];
  const checkInput = (name, pathKey, keyName) => {
    const data = inputs[name];
    if (!data) {
      diagnostics.push({
        severity: 'error',
        message: `Missing or unreadable input file: ${paths[pathKey]}`,
      });
      return false;
    }
    const rows = data[keyName];
    if (!Array.isArray(rows)) {
      diagnostics.push({
        severity: 'error',
        message: `Malformed input file: ${paths[pathKey]} (expected array under key '${keyName}')`,
      });
      return false;
    }
    return true;
  };

  checkInput('wave1CandidateQa', 'wave1CandidateQaIn', 'rows');
  checkInput('sourceFigureCandidates', 'sourceFigureCandidatesIn', 'rows');
  checkInput('rightsOverlay', 'rightsOverlayIn', 'rows');
  checkInput('sourceMap', 'sourceMapIn', 'rows');
  checkInput('sourceDocumentRegistry', 'sourceDocumentRegistryIn', 'registry');

  return diagnostics;
}

export function buildSourceVisualReceiptReplayHarness(options = {}) {
  const root = rootFromOptions(options);
  const paths = { ...DEFAULT_PATHS, ...(options.paths ?? {}) };
  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
  const inputs = loadInputs(root, paths, options);
  const diagnostics = validateInputs(inputs, paths);
  const rawWave1Rows = rowsOf(inputs.wave1CandidateQa);
  const wave1Rows = rawWave1Rows.filter((row, index) => {
    if (!row || typeof row !== 'object') {
      diagnostics.push({
