    if (!questionKeyOf(row)) {
      diagnostics.push({
        severity: 'warning',
        message: `Skipping row at index ${index} in wave1CandidateQa due to missing question key`,
      });
      return false;
    }
    return true;
  });
  const indexes = {
    sourceFigureByQuestionKey: indexBy(rowsOf(inputs.sourceFigureCandidates), questionKeyOf),
    rightsByQuestionKey: indexBy(rowsOf(inputs.rightsOverlay), questionKeyOf),
    sourceMapByQuestionKey: indexBy(rowsOf(inputs.sourceMap), questionKeyOf),
    sourceRegistryByDocumentId: indexBy(rowsOf(inputs.sourceDocumentRegistry), (row) => firstString(row?.source_document_id)),
  };
  const rows = wave1Rows.map((qaRow, rowIndex) => buildReplayCandidate({
