  const candidates = buildCandidatesArtifact(rows, generatedAt);
  const refs = buildRefsArtifact(rows, paths, generatedAt);
  const readback = buildReadback(rows, Boolean(inputs.wave1CandidateQa), generatedAt);
  const validator = buildValidator({ rows, refs, readback, generatedAt, diagnostics });

