![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

To prevent diff churn and maintain consistency across generated artifacts, we should sort JSON arrays by their ID fields (such as `question_key`). Since these are alphanumeric identifiers, we should use a null-safe natural string comparison to prevent unstable sorting or errors if keys are nullish.

```javascript
function buildCandidatesArtifact(rows, generatedAt) {
  const sortedRows = [...rows].sort((a, b) => {
    const keyA = a.question_key ?? '';
    const keyB = b.question_key ?? '';
    return keyA.localeCompare(keyB, undefined, { numeric: true, sensitivity: 'base' });
  });
  return {
    schema_version: 'source_visual_receipt_replay_candidates.v1',
    generated_at: generatedAt,
    generated_by: 'build-source-visual-receipt-replay-harness.mjs',
    issue: 1197,
    parent_issue: 1185,
    depends_on_issues: [1196],
    boundary: {
      candidate_replay_only: true,
      creates_final_display_acceptance: false,
      creates_source_visual_receipt_approval: false,
      performs_remote_supabase_mutation: false,
      performs_external_vlm_call: false,
    },
    rows: sortedRows,
  };
}

function buildRefsArtifact(rows, paths, generatedAt) {
  const sortedRows = [...rows].sort((a, b) => {
    const keyA = a.question_key ?? '';
    const keyB = b.question_key ?? '';
    return keyA.localeCompare(keyB, undefined, { numeric: true, sensitivity: 'base' });
  });
  return {
    schema_version: 'source_visual_receipt_replay_refs.v1',
    generated_at: generatedAt,
    posture: 'candidate_replay_only_no_final_display_acceptance',
    accepted_source_visual_receipt_refs: [],
    rows: sortedRows.map((row, index) => ({
      schema_version: 'source_visual_receipt_replay_ref.v1',
      question_key: row.question_key,
      question_ref: row.question_ref,
      source_visual_receipt_id: row.source_visual_receipt_id,
      receipt_candidate_id: row.receipt_candidate_id,
      review_status: row.review_status,
      replay_status: row.replay_status,
      blockers: row.blockers,
      audit_hash: row.audit_hash,
      source_visual_receipt_approved: false,
      student_display_eligible_final: false,
      source_ref: { 
        path: paths.outputCandidatePath,
        json_pointer: `/rows/${index}`,
      },
    })),
    replay_candidate_refs: sortedRows.map((row, index) => ({
      source_visual_receipt_id: row.source_visual_receipt_id,
      receipt_candidate_id: row.receipt_candidate_id,
      source_ref: {
        path: paths.outputCandidatePath,
        json_pointer: `/rows/${index}`,
      },
    })),
  };
}
```

<details>
<summary>References</summary>

1. When sorting alphanumeric or potentially non-numeric identifiers (such as variants or question numbers), avoid arithmetic subtraction which can yield NaN and cause unstable sorting. Use a null-safe natural string comparison instead.
2. When sorting strings that can be null or undefined, use a null-safe natural string comparator to prevent calling localeCompare directly on nullish values.
</details>

